mapper.select:
SELECT
,xuesheng.xuesheng_name as xueshengName ,xuesheng.xuesheng_xuehao as xueshengXuehao ,xuesheng.xuesheng_phone as xueshengPhone ,xuesheng.xuesheng_email as xueshengEmail ,xuesheng.yuanxi_types as yuanxiTypes ,xuesheng.zhuanye_types as zhuanyeTypes ,xuesheng.banji_types as banjiTypes ,laoshi.laoshi_name as laoshiName ,huifu_laoshi.laoshi_name as huifuLaoshiName FROM wenti_jieda a LEFT JOIN xuesheng xuesheng ON a.xuesheng_id = xuesheng.id LEFT JOIN laoshi laoshi ON a.laoshi_id = laoshi.id LEFT JOIN laoshi huifu_laoshi ON a.huifu_laoshi_id = huifu_laoshi.id
and a.id in
#{item}
and a.xuesheng_id = #{params.xueshengId}
and a.laoshi_id = #{params.laoshiId}
and (a.laoshi_id = #{params.teacherScopeId} or a.laoshi_id is null)
and xuesheng.yuanxi_types = #{params.yuanxiTypes}
and xuesheng.zhuanye_types = #{params.zhuanyeTypes}
and xuesheng.banji_types = #{params.banjiTypes}
and a.wenti_title like CONCAT('%',#{params.wentiTitle},'%')
and a.wenti_content like CONCAT('%',#{params.wentiContent},'%')
and a.wenti_status = #{params.wentiStatus}
and xuesheng.xuesheng_name like CONCAT('%',#{params.xueshengName},'%')
and xuesheng.xuesheng_xuehao like CONCAT('%',#{params.xueshengXuehao},'%')
and laoshi.laoshi_name like CONCAT('%',#{params.laoshiName},'%')
order by a.${params.orderBy} desc
